create table public.product_variants (id uuid primary key default gen_random_uuid(), store_id uuid not null, product_id uuid not null, sku text not null, barcode text, title text not null, option_values jsonb not null default '{}'::jsonb, price_minor bigint not null check(price_minor >= 0), compare_at_price_minor bigint check(compare_at_price_minor is null or compare_at_price_minor >= 0), currency char(3) not null default 'INR', is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(store_id,product_id) references public.products(store_id,id) on delete cascade, unique(store_id,sku), unique(store_id,id));
